198	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
199		var req deviceRequest
200		if !decodeJSONBody(w, r, &req) {
201			return
202		}
203		if req.DeviceID == "" {
204			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
205			return
206		}
207	
208		created, err := s.RegisterDevice(req.DeviceID)
209		if err != nil {
210			writeError(w, http.StatusInternalServerError, "failed to register device")
211			return
212		}
213	
214		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
215	}
