262	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
263		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
264	
265		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
266		if err != nil || mediaType != "application/json" {
267			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
268			return
269		}
270	
271		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
272		var req postRequest
273		dec := json.NewDecoder(r.Body)
274		if err := dec.Decode(&req); err != nil {
275			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
276			return
277		}
278		// Reject trailing data after the JSON object.
279		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
280			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
281			return
282		}
283	
284		if req.DeviceID == "" {
285			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
286			return
287		}
288		if len(req.Changes) == 0 {
289			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
290			return
291		}
292	
293		changes := make([]store.Change, len(req.Changes))
294		seen := make(map[string]struct{}, len(req.Changes))
295		for i, c := range req.Changes {
296			if c.ID == "" {
297				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
298				return
299			}
300			if len(c.Payload) == 0 {
301				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
302				return
303			}
304			if _, dup := seen[c.ID]; dup {
305				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
306				return
307			}
308			seen[c.ID] = struct{}{}
309			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
310		}
311	
312		results, err := s.PostChanges(documentID, changes)
313		if err != nil {
314			var conflict *store.ErrConflict
315			if errors.As(err, &conflict) {
316				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
317				return
318			}
319			writeError(w, http.StatusInternalServerError, "failed to commit changes")
320			return
321		}
322	
323		writeJSON(w, http.StatusOK, map[string]any{"results": results})
324	}
