326	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
327		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
328	
329		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
330		if err != nil || mediaType != "application/json" {
331			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
332			return
333		}
334	
335		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
336		var req mergeRequest
337		dec := json.NewDecoder(r.Body)
338		if err := dec.Decode(&req); err != nil {
339			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
340			return
341		}
342		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
343			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
344			return
345		}
346	
347		if req.DeviceID == "" {
348			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
349			return
350		}
351		// baseCursor must be present and a non-negative integer (no fractions,
352		// strings, booleans or null).
353		if len(req.BaseCursor) == 0 {
354			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
355			return
356		}
357		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
358		if !ok {
359			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
360			return
361		}
362		if req.Change == nil {
363			writeError(w, http.StatusBadRequest, "change must be an object")
364			return
365		}
366		if req.Change.ID == "" {
367			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
368			return
369		}
370		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
371			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
372			return
373		}
374	
375		result, err := s.MergeChange(documentID, baseCursor, store.Change{
376			ID:       req.Change.ID,
377			DeviceID: req.DeviceID,
378			Payload:  req.Change.Payload,
379		})
380		if err != nil {
381			var conflict *store.ErrConflict
382			switch {
383			case errors.Is(err, store.ErrStaleCursor):
384				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
385				return
386			case errors.As(err, &conflict):
387				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
388				return
389			default:
390				writeError(w, http.StatusInternalServerError, "failed to merge change")
391				return
392			}
393		}
394	
395		writeJSON(w, http.StatusOK, result)
396	}
