448	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
449		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
450	
451		cursor, ok := parseCursorPath(r.PathValue("cursor"))
452		if !ok {
453			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
454			return
455		}
456	
457		state, err := s.GetSnapshot(documentID, cursor)
458		if err != nil {
459			if errors.Is(err, store.ErrSnapshotNotFound) {
460				writeError(w, http.StatusNotFound, "snapshot not found")
461				return
462			}
463			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
464			return
465		}
466	
467		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
468	}
