510	func TestConcurrentSessionLifecycleHTTP(t *testing.T) {
511		h, _ := newTestHandler(t)
512		registerDevice(t, h, "dev")
513	
514		// Concurrent identical creates: exactly one creator.
515		const n = 40
516		var wg sync.WaitGroup
517		var mu sync.Mutex
518		creators := 0
519		errs := make(chan error, n)
520		for i := 0; i < n; i++ {
521			wg.Add(1)
522			go func() {
523				defer wg.Done()
524				w, body := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
525				if w.Code != http.StatusOK {
526					errs <- fmt.Errorf("status %d: %s", w.Code, w.Body.String())
527					return
528				}
529				if body["created"] == true {
530					mu.Lock()
531					creators++
532					mu.Unlock()
533				}
534			}()
535		}
536		wg.Wait()
537		close(errs)
538		for err := range errs {
539			t.Fatal(err)
540		}
541		if creators != 1 {
542			t.Fatalf("creators = %d, want 1", creators)
543		}
544	
545		// Concurrent delete vs. create: in the end exactly one of {live, absent}
546		// holds consistently, and the next state is coherent (repeat delete 404s
547		// iff the delete won; create reports created=true iff it ran after removal).
548		var wg2 sync.WaitGroup
549		statuses := make(chan int, 2)
550		wg2.Add(2)
551		go func() {
552			defer wg2.Done()
553			w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
554			statuses <- w.Code
555		}()
556		go func() {
557			defer wg2.Done()
558			w, _ := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
559			statuses <- w.Code
560		}()
561		wg2.Wait()
562		close(statuses)
563		for code := range statuses {
564			if code != http.StatusOK {
565				t.Fatalf("racing delete/create status = %d", code)
566			}
567		}
568	
569		// The race settles into exactly one coherent state (live or absent). A
570		// final owner delete then forces "absent": 200 if it was live, 404 if the
571		// racing delete already won. Afterwards both the read and a repeat delete
572		// must observe the same absent state — no half-deleted or duplicated row.
573		w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
574		if w.Code != http.StatusOK && w.Code != http.StatusNotFound {
575			t.Fatalf("settling delete = %d", w.Code)
576		}
577		w, _ = doRequest(t, h, http.MethodGet, "/v1/sessions/hot/documents/d/changes")
578		if w.Code != http.StatusNotFound {
579			t.Fatalf("session should be absent after settle, GET = %d", w.Code)
580		}
581		w, _ = doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
582		if w.Code != http.StatusNotFound {
583			t.Fatalf("repeat delete after settle = %d, want 404", w.Code)
584		}
585	}
