	created, err := s.CreateSession("dev-1", "sess")
	if err != nil || !created {
		t.Fatalf("first create = created:%v err:%v", created, err)
	}
	if exists, err := s.SessionExists("sess"); err != nil || !exists {
		t.Fatalf("session should exist: exists=%v err=%v", exists, err)
	}

